CREATE TYPE "operational_task_lifecycle_stage" AS ENUM ('upcoming_reminder','due_notification','overdue_notification','manager_notification','escalated');
CREATE TABLE "operational_task_lifecycle_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL,"occurrence_id" uuid NOT NULL,"stage" "operational_task_lifecycle_stage" NOT NULL,"recipient_user_id" text,"processed_at" timestamptz DEFAULT now() NOT NULL,"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "operational_task_lifecycle_events_tenant_occurrence_fk" FOREIGN KEY ("tenant_id","occurrence_id") REFERENCES "operational_task_occurrences"("tenant_id","id") ON DELETE cascade);
CREATE UNIQUE INDEX "operational_task_lifecycle_events_stage_ux" ON "operational_task_lifecycle_events" ("tenant_id","occurrence_id","stage","recipient_user_id");
